### c1/step1 1
{"new_theses": [{"local_id": "t1", "description": "How much credit support or guarantee exposure will NVIDIA have signed for AI cloud partners under its new revenue-sharing and credit-support model by 2027-12-31?", "outcome": "The amount of signed credit-support, guarantee, or similar credit-enhancement commitments NVIDIA discloses for AI cloud partners under the new model.", "period": "2027-12-31 (check date within 18 months of the 2026-07-01 item, for an unsigned obligation)", "opens_as": "binding_obligation", "settled_by": "NVIDIA's annual report/Form 10-K, 8-K, or other filing disclosures of guarantees, credit support, and commitments, and signed partner agreements.", "closest_open_thesis": null, "why_a_separate_bet": "No open thesis covers NVIDIA's credit exposure from this model; tracking signed credit-support commitments separately isolates potential cash and credit risk from the company's product-demand and revenue-growth questions."}], "evidence": [{"local_id": "e1", "summary": "NVIDIA announced a new business model in which AI clouds can procure NVIDIA infrastructure for AI-native, enterprise and ISV customers under a revenue-sharing and credit-support arrangement. NVIDIA said the AI clouds will sell NVIDIA-powered cloud services, with NVIDIA earning standard product revenue plus a share of cloud revenue on the supported capacity, and that this provides NVIDIA with a recurring, usage-linked earnings stream.", "source_passages": ["NVIDIA is partnering with AI clouds to deploy large‑scale, multi‑tenant AI factories, aligning economics through a revenue-sharing and credit-support model.", "To address this, NVIDIA is introducing a new business model that opens up compute access to the fast‑growing AI ecosystem of startups, model builders, enterprises, research organizations and regional AI players.", "This new model enables AI clouds to procure NVIDIA infrastructure for AI-native, enterprise and ISV customers through economic alignment with a revenue-sharing and credit-support model. Through the partnership, AI clouds will sell NVIDIA-powered cloud services, with NVIDIA earning both standard product revenue and a share of the cloud revenue on the supported capacity. This structure accelerates adoption of NVIDIA platforms among the high-growth, high-conviction AI native sector, and provides NVIDIA with a recurring, usage-linked earnings stream."], "original_party": "NVIDIA Corporation", "reporting_speaker": "NVIDIA Corporation", "tier": "fact", "statement_date": "2026-07-01", "statement_date_text": "2026-07-01", "evidence_period": null, "links": [{"target_type": "new", "target_id": "t1", "relevance": "Announces the credit-support and revenue-sharing model whose signed commitments or guarantees the thesis tracks; the item does not quantify the support."}], "figures": [], "verified_source_passages": ["NVIDIA is partnering with AI clouds to deploy large‑scale, multi‑tenant AI factories, aligning economics through a revenue-sharing and credit-support model.", "To address this, NVIDIA is introducing a new business model that opens up compute access to the fast‑growing AI ecosystem of startups, model builders, enterprises, research organizations and regional AI players.", "This new model enables AI clouds to procure NVIDIA infrastructure for AI-native, enterprise and ISV customers through economic alignment with a revenue-sharing and credit-support model. Through the partnership, AI clouds will sell NVIDIA-powered cloud services, with NVIDIA earning both standard product revenue and a share of the cloud revenue on the supported capacity. This structure accelerates adoption of NVIDIA platforms among the high-growth, high-conviction AI native sector, and provides NVIDIA with a recurring, usage-linked earnings stream."], "source_passages_repaired": [false, false, false]}, {"local_id": "e2", "summary": "Firmus Technologies is building a DSX AI factory campus in Batam, Indonesia, which is expected to scale to 360 megawatts and up to 170,000 NVIDIA GPUs. Firmus co-CEO Tim Rosenfield said the company is building a NVIDIA DSX-aligned AI factory to help more customers access compute.", "source_passages": ["Firmus is building a DSX AI factory campus in Batam, Indonesia. The campus is expected to scale to 360 megawatts and up to 170,000 NVIDIA GPUs.", "“AI-native companies need access to scalable, energy- and cost-efficient compute infrastructure to compete globally,” said Tim Rosenfield, co-CEO of Firmus Technologies. “Firmus AI cloud is building a NVIDIA DSX-aligned AI factory, which will enable our cloud to help more customers access the compute they need to build and scale AI.”"], "original_party": "Firmus Technologies", "reporting_speaker": "NVIDIA Corporation blog", "tier": "party_statement", "statement_date": null, "statement_date_text": null, "evidence_period": null, "links": [{"target_type": "new", "target_id": "t1", "relevance": "Names one AI cloud partner building a 360-megawatt, up-to-170,000-GPU DSX campus under the initiative that the credit-support model is meant to support; the item does not state any NVIDIA guarantee or credit-support amount for Firmus."}], "figures": [], "verified_source_passages": ["Firmus is building a DSX AI factory campus in Batam, Indonesia. The campus is expected to scale to 360 megawatts and up to 170,000 NVIDIA GPUs.", "“AI-native companies need access to scalable, energy- and cost-efficient compute infrastructure to compete globally,” said Tim Rosenfield, co-CEO of Firmus Technologies. “Firmus AI cloud is building a NVIDIA DSX-aligned AI factory, which will enable our cloud to help more customers access the compute they need to build and scale AI.”"], "source_passages_repaired": [false, false]}], "unresolved_links": [], "figure_issues": [], "unfiled_evidence": [], "unlinked_new_thesis_ids": [], "new_thesis_ids": {"t1": "clean-1"}}

### c1/step1 8
{"new_theses": [], "evidence": [{"local_id": "e1", "summary": "The Information reported on July 1 that NVIDIA is providing financial guarantees to young cloud service providers that lease or rent its GPUs: if these companies fail to secure enough AI developers to rent their computing capacity, NVIDIA will repurchase their unsold GPU capacity at a pre-agreed price. In return, NVIDIA will receive a percentage of these cloud providers' revenue, with the revenue-sharing rate gradually declining over the contract term. GPU cloud providers Firmus and Sharon AI have already joined the program, and three executives with existing business ties to NVIDIA confirmed the arrangement; an NVIDIA spokesperson also confirmed the program's existence.", "source_passages": ["On July 1, according to the technology news outlet The Information, NVIDIA is providing financial guarantees to young cloud service providers that lease or rent its GPUs—if these companies fail to secure enough AI developers to rent their computing capacity, NVIDIA will repurchase their unsold GPU capacity at a pre-agreed price.", "In return, NVIDIA will receive a percentage of these cloud providers’ revenue, with the revenue-sharing rate gradually declining over the term of the contract. GPU cloud providers Firmus and Sharon AI have already joined the program, and three executives with existing business ties to NVIDIA confirmed the arrangement.", "According to the report, the initiative is internally referred to by some NVIDIA personnel as the 'AI Compute Partnership.' A NVIDIA spokesperson also confirmed the existence of the program."], "original_party": "NVIDIA", "reporting_speaker": "The Information", "tier": "rumour", "statement_date": "2026-07-01", "statement_date_text": "July 1", "evidence_period": null, "links": [{"target_type": "existing", "target_id": "clean-1", "relevance": "Gives the specific credit-support terms — repurchase of unsold GPU capacity at a pre-agreed price plus a declining revenue share, with Firmus and Sharon AI as participants — informing the amount and structure of guarantee exposure the thesis tracks."}], "figures": [], "verified_source_passages": ["On July 1, according to the technology news outlet The Information, NVIDIA is providing financial guarantees to young cloud service providers that lease or rent its GPUs—if these companies fail to secure enough AI developers to rent their computing capacity, NVIDIA will repurchase their unsold GPU capacity at a pre-agreed price.", "In return, NVIDIA will receive a percentage of these cloud providers’ revenue, with the revenue-sharing rate gradually declining over the term of the contract. GPU cloud providers Firmus and Sharon AI have already joined the program, and three executives with existing business ties to NVIDIA confirmed the arrangement.", "According to the report, the initiative is internally referred to by some NVIDIA personnel as the 'AI Compute Partnership.' A NVIDIA spokesperson also confirmed the existence of the program."], "source_passages_repaired": [false, false, false]}, {"local_id": "e2", "summary": "On July 1, NVIDIA published a statement on its official website announcing a new business model that combines revenue sharing with credit support, enabling AI cloud providers to procure NVIDIA infrastructure without bearing the full upfront capital expenditure and to offer computing services to downstream AI-native enterprises, model developers and corporate clients. Per the official press release, NVIDIA will earn standard product revenue plus an additional share of cloud service revenue, creating a usage-based recurring revenue stream; the company positions the framework as its 'DSX AI Factory' model. Sharon AI and Firmus are the first cloud providers participating in the model.", "source_passages": ["On July 1, NVIDIA published a statement on its official website announcing a new business model that combines revenue sharing with credit support, enabling AI cloud providers to procure NVIDIA infrastructure without bearing the full upfront capital expenditure, and allowing them to offer computing services to downstream AI-native enterprises, model developers, and corporate clients.", "According to NVIDIA’s official press release, the company will earn not only standard product revenue but also an additional share of cloud service revenue, creating a usage-based, recurring revenue stream.", "NVIDIA positions this framework as the 'DSX AI Factory' model, targeting AI service scenarios requiring continuous cross-regional operations, high utilization rates, and multi-tenant accelerated computing.", "Sharon AI and Firmus are the first cloud providers participating in this model."], "original_party": "NVIDIA", "reporting_speaker": "moomoo.com (relaying NVIDIA's press release)", "tier": "fact", "statement_date": "2026-07-01", "statement_date_text": "July 1", "evidence_period": null, "links": [{"target_type": "existing", "target_id": "clean-1", "relevance": "NVIDIA's own announcement of the revenue-sharing plus credit-support model, including an additional usage-based cloud-revenue stream; establishes the model under which the guarantee exposure tracked by the thesis will be signed."}], "figures": [], "verified_source_passages": ["On July 1, NVIDIA published a statement on its official website announcing a new business model that combines revenue sharing with credit support, enabling AI cloud providers to procure NVIDIA infrastructure without bearing the full upfront capital expenditure, and allowing them to offer computing services to downstream AI-native enterprises, model developers, and corporate clients.", "According to NVIDIA’s official press release, the company will earn not only standard product revenue but also an additional share of cloud service revenue, creating a usage-based, recurring revenue stream.", "NVIDIA positions this framework as the 'DSX AI Factory' model, targeting AI service scenarios requiring continuous cross-regional operations, high utilization rates, and multi-tenant accelerated computing.", "Sharon AI and Firmus are the first cloud providers participating in this model."], "source_passages_repaired": [false, false, false, false]}, {"local_id": "e3", "summary": "As the first participants in NVIDIA's model, Sharon AI plans to deploy up to 40,000 NVIDIA Grace Blackwell GB300 GPUs, and Firmus is constructing a DSX AI Factory campus in Batam, Indonesia, expected to scale up to 360 megawatts and accommodate up to 170,000 NVIDIA GPUs.", "source_passages": ["Sharon AI plans to deploy up to 40,000 NVIDIA Grace Blackwell GB300 GPUs, while Firmus is constructing a DSX AI Factory campus in Batam, Indonesia, expected to scale up to 360 megawatts and accommodate up to 170,000 NVIDIA GPUs."], "original_party": "Sharon AI; Firmus", "reporting_speaker": "moomoo.com", "tier": "fact", "statement_date": null, "statement_date_text": null, "evidence_period": null, "links": [], "figures": [], "verified_source_passages": ["Sharon AI plans to deploy up to 40,000 NVIDIA Grace Blackwell GB300 GPUs, while Firmus is constructing a DSX AI Factory campus in Batam, Indonesia, expected to scale up to 360 megawatts and accommodate up to 170,000 NVIDIA GPUs."], "source_passages_repaired": [false]}, {"local_id": "e4", "summary": "According to prior reporting by The Information, NVIDIA has recently been negotiating to provide financial guarantees for OpenAI's lease of a large data center in Ohio — an asset that, if fully built out at current prices for chips, labor, power and other materials, could cost as much as $500 billion.", "source_passages": ["According to prior reporting by The Information, NVIDIA has also recently been negotiating to provide financial guarantees for OpenAI’s lease of a large data center in Ohio—an asset that, if fully built out at current prices for chips, labor, power, and other materials, could cost as much as $500 billion."], "original_party": "NVIDIA", "reporting_speaker": "The Information", "tier": "rumour", "statement_date": null, "statement_date_text": "prior reporting", "evidence_period": null, "links": [{"target_type": "existing", "target_id": "clean-1", "relevance": "A reported potential guarantee for an AI cloud partner's large Ohio data center lease (asset up to $500 billion) is a prospective credit-support commitment informing the exposure amount the thesis tracks."}], "figures": [], "verified_source_passages": ["According to prior reporting by The Information, NVIDIA has also recently been negotiating to provide financial guarantees for OpenAI’s lease of a large data center in Ohio—an asset that, if fully built out at current prices for chips, labor, power, and other materials, could cost as much as $500 billion."], "source_passages_repaired": [false]}, {"local_id": "e5", "summary": "According to a regulatory filing NVIDIA submitted in May 2026 (covering the quarter ended in April), NVIDIA subsequently added another $3.5 billion to guarantee customer data center leases in exchange for rights to purchase their shares.", "source_passages": ["According to a regulatory filing submitted by NVIDIA in May of this year (covering the quarter ended in April), NVIDIA subsequently added another $3.5 billion to guarantee customer data center leases in exchange for rights to purchase their shares."], "original_party": "NVIDIA", "reporting_speaker": "moomoo.com (citing NVIDIA's regulatory filing)", "tier": "fact", "statement_date": null, "statement_date_text": "May of this year", "evidence_period": "quarter ended April 2026", "links": [{"target_type": "existing", "target_id": "clean-1", "relevance": "NVIDIA's disclosed $3.5 billion addition to guarantees for customer data center leases is credit-support exposure of exactly the kind the thesis quantifies, bearing on the running guarantee total."}], "figures": [{"measure": "guarantees added for customer data center leases", "period": "quarter ended April 2026", "value": "$3.5 billion", "kind": "actual", "basis": "in exchange for rights to purchase customer shares; disclosed in a regulatory filing submitted May 2026"}], "verified_source_passages": ["According to a regulatory filing submitted by NVIDIA in May of this year (covering the quarter ended in April), NVIDIA subsequently added another $3.5 billion to guarantee customer data center leases in exchange for rights to purchase their shares."], "source_passages_repaired": [false]}], "unresolved_links": [], "figure_issues": [], "unfiled_evidence": [], "unlinked_new_thesis_ids": [], "new_thesis_ids": {}}

### c1/step1 42
{"new_theses": [{"local_id": "new-shared-1", "description": "How much will the big four AI hyperscalers spend in combined data center capital expenditures in calendar 2026?", "outcome": "The sum of calendar-2026 data center capex actually reported by the big four AI hyperscalers, versus the roughly $650 billion they are reported to plan for this year.", "period": "Calendar 2026; settled by the four hyperscalers' full-year 2026 capex disclosures in their Q4 2026 earnings reports (January–February 2027), the release date of the quantity.", "opens_as": "shared_quantity", "settled_by": "The four AI hyperscalers' quarterly earnings releases and annual 10-K filings reporting calendar-2026 capital expenditures.", "closest_open_thesis": "clean-1", "why_a_separate_bet": "clean-1 tracks NVIDIA's own signed credit-support/guarantee exposure to AI cloud partners, while this thesis tracks the customers' aggregate capex pool that drives demand for NVIDIA's products. They can move apart: hyperscaler capex can rise while NVIDIA signs no new guarantees (or the customers spend on rivals' silicon), and NVIDIA can expand its guarantee commitments to neoclouds while hyperscaler capex disappoints."}], "evidence": [{"local_id": "ev-1", "summary": "The article reports that the big four AI hyperscalers plan to spend around $650 billion on data center capital expenditures in the current year (2026). This is a planned spending level by the customer group, not a committed order for NVIDIA.", "source_passages": ["The big four AI hyperscalers plan to spend around $650 billion on data center capital expenditures this year."], "original_party": "The big four AI hyperscalers", "reporting_speaker": "fool.com (Motley Fool) article author", "tier": "party_statement", "statement_date": null, "statement_date_text": null, "evidence_period": "2026 (\"this year\", as stated)", "links": [{"target_type": "new", "target_id": "new-shared-1", "relevance": "Sets the planned level of the big four hyperscalers' combined data center capex for calendar 2026, the demand pool underpinning NVIDIA's GPU sales; it is a plan, not a NVIDIA order or revenue."}], "figures": [], "verified_source_passages": ["The big four AI hyperscalers plan to spend around $650 billion on data center capital expenditures this year."], "source_passages_repaired": [false]}, {"local_id": "ev-2", "summary": "NVIDIA projects that the big four AI hyperscalers' combined data center capital expenditures could reach $1 trillion next year (2027), up from the roughly $650 billion planned for 2026. This is NVIDIA's own projection, not a reported outcome.", "source_passages": ["The big four AI hyperscalers plan to spend around $650 billion on data center capital expenditures this year. Next year, Nvidia projects that this figure could reach $1 trillion."], "original_party": "NVIDIA", "reporting_speaker": "fool.com (Motley Fool) article author", "tier": "party_statement", "statement_date": null, "statement_date_text": null, "evidence_period": "2027 (\"next year\", as stated)", "links": [{"target_type": "new", "target_id": "new-shared-1", "relevance": "NVIDIA's own projection of the hyperscaler capex pool for 2027 signals the expected growth of demand beyond the 2026 level; it is a forecast for a later year, not the 2026 answer."}], "figures": [], "verified_source_passages": ["The big four AI hyperscalers plan to spend around $650 billion on data center capital expenditures this year. Next year, Nvidia projects that this figure could reach $1 trillion."], "source_passages_repaired": [false]}, {"local_id": "ev-3", "summary": "Wall Street analysts project NVIDIA revenue growth of 82% this year (2026) and 41% next year (2027), per the article. These are sell-side consensus growth estimates, not reported results or company guidance.", "source_passages": ["Wall Street analysts project 82% revenue growth for this year and 41% next year, so there's another external source that's projecting even more growth for Nvidia."], "original_party": "Wall Street analysts (consensus)", "reporting_speaker": "fool.com (Motley Fool) article author", "tier": "third_party_view", "statement_date": null, "statement_date_text": null, "evidence_period": "2026 and 2027 (\"this year and next year\", as stated)", "links": [], "figures": [{"measure": "revenue growth", "period": "2026 (\"this year\", as stated)", "value": "82%", "kind": "estimate", "basis": "Wall Street analysts' projection for NVIDIA, calendar year as stated in the article"}, {"measure": "revenue growth", "period": "2027 (\"next year\", as stated)", "value": "41%", "kind": "estimate", "basis": "Wall Street analysts' projection for NVIDIA, calendar year as stated in the article"}], "verified_source_passages": ["Wall Street analysts project 82% revenue growth for this year and 41% next year, so there's another external source that's projecting even more growth for Nvidia."], "source_passages_repaired": [false]}], "unresolved_links": [], "figure_issues": [], "unfiled_evidence": [], "unlinked_new_thesis_ids": [], "new_thesis_ids": {"new-shared-1": "clean-6"}}

### c1/step1 127
{"new_theses": [{"local_id": "new-compute-price", "description": "What will the spot rental price of an hour of Nvidia H100 GPU compute average over calendar 2026, after peaking around $3.20/hour in May 2026 and then declining?", "outcome": "The realized spot rental price for an hour of H100 GPU time over calendar 2026, versus the ~$3.20/hour May 2026 peak.", "period": "Calendar 2026 (check date 2026-12-31); set from the item's reported May-2026 peak (~$3.20/hour) and subsequent decline in the H100 spot-rate series.", "opens_as": "shared_quantity", "settled_by": "Ornn and other GPU compute marketplaces' published H100 spot-rate data (e.g., Ornn's index) covering calendar 2026.", "closest_open_thesis": "clean-6", "why_a_separate_bet": "clean-6 tracks big-four hyperscaler capex (AI-infrastructure demand), which can keep rising while GPU compute rental prices fall on growing accelerator supply and custom-silicon competition; the compute price reflects Nvidia's pricing power and can move opposite to total spend."}, {"local_id": "new-memory-price", "description": "What will happen to HBM/DRAM contract prices over the 12 months to mid-2027, after rising roughly tenfold over the past year and becoming the data-center bottleneck?", "outcome": "The change in HBM/DRAM contract prices over the 12 months to mid-2027, versus the roughly tenfold rise over the prior year.", "period": "The 12 months to 2027-06-30 (next calendar year); set from the item's report that memory prices rose tenfold over the past year and its view that conditions will persist absent an HBM breakthrough.", "opens_as": "shared_quantity", "settled_by": "TrendForce quarterly DRAM/HBM contract-price releases and Micron's quarterly HBM pricing and revenue disclosures through mid-2027.", "closest_open_thesis": "clean-9", "why_a_separate_bet": "clean-9 tracks the dollar amount of Nvidia's own supply/purchase commitments, a company decision about how much input capacity it locks in; HBM/DRAM market prices are set by the memory industry's supply and demand and can rise or fall independently of how much Nvidia commits."}], "evidence": [{"local_id": "ev-1", "summary": "Ornn's GPU compute-marketplace data, cited by TechCrunch, show the spot price for an hour of Nvidia H100 GPU time peaked at around $3.20 an hour in May 2026 and has since declined steadily over the past year; the article contends Nvidia's value as a company is tied to this compute price, which is falling.", "source_passages": ["In comparison, this (via the compute market Ornn ) is how the spot price for an hour of time on an Nvidia H100 GPU has changed over the last year:", "Just like Nvidia’s stock price, there’s a peak in May (around $3.20 an hour) and then a steady drop-off. For better or worse, Nvidia’s value as a company is tied to the price of compute and that price is falling."], "original_party": "Ornn (GPU compute marketplace)", "reporting_speaker": "Russell Brandom / TechCrunch", "tier": "fact", "statement_date": null, "statement_date_text": null, "evidence_period": "The 12 months to mid-2026 (peak in May 2026)", "links": [{"target_type": "new", "target_id": "new-compute-price", "relevance": "Directly reports the H100 spot rental price level (~$3.20/hour May 2026 peak) and its decline, which is the quantity the thesis tracks."}], "figures": [], "verified_source_passages": ["In comparison, this (via the compute market Ornn ) is how the spot price for an hour of time on an Nvidia H100 GPU has changed over the last year:", "Just like Nvidia’s stock price, there’s a peak in May (around $3.20 an hour) and then a steady drop-off. For better or worse, Nvidia’s value as a company is tied to the price of compute and that price is falling."], "source_passages_repaired": [false, false]}, {"local_id": "ev-2", "summary": "Memory-chip makers such as Micron have been able to raise prices roughly tenfold over the past year as data-center demand outran supply, making high-bandwidth/DRAM memory the new bottleneck for data centers, according to TechCrunch.", "source_passages": ["For memory companies like Micron, the story is much simpler. They build high-bandwidth memory chips — specialized components designed to move data in and out of processors as fast as possible — which have been getting incrementally better for 20 years. Without the chips or the companies changing too much, the service they provide suddenly became very valuable — and since demand is growing faster than anyone can scale up supply, they have been able to increase prices tenfold over the past year."], "original_party": "Memory manufacturers (Micron and peers)", "reporting_speaker": "Russell Brandom / TechCrunch", "tier": "fact", "statement_date": null, "statement_date_text": null, "evidence_period": "The year to mid-2026", "links": [{"target_type": "new", "target_id": "new-memory-price", "relevance": "The reported ~tenfold HBM/DRAM price increase and memory bottleneck is the baseline the thesis compares future memory prices against."}], "figures": [], "verified_source_passages": ["For memory companies like Micron, the story is much simpler. They build high-bandwidth memory chips — specialized components designed to move data in and out of processors as fast as possible — which have been getting incrementally better for 20 years. Without the chips or the companies changing too much, the service they provide suddenly became very valuable — and since demand is growing faster than anyone can scale up supply, they have been able to increase prices tenfold over the past year."], "source_passages_repaired": [false]}, {"local_id": "ev-3", "summary": "Google, Amazon, Microsoft, and OpenAI have each launched their own custom AI processors to lessen their dependence on Nvidia; according to TechCrunch, even if those chips are not as capable as Nvidia's latest GPUs, they are good enough to drive down the price of compute.", "source_passages": ["Google , Amazon , Microsoft , and even OpenAI have launched their own custom processors to lessen their dependence on Nvidia; even if those chips aren't as good as the latest model from Nvidia, they're good enough to drive down the price of compute."], "original_party": "Google, Amazon, Microsoft, OpenAI", "reporting_speaker": "Russell Brandom / TechCrunch", "tier": "fact", "statement_date": null, "statement_date_text": null, "evidence_period": null, "links": [{"target_type": "new", "target_id": "new-compute-price", "relevance": "Competing custom accelerators from major customers are cited as a force pushing the price of Nvidia GPU compute down, informing the thesis on H100 spot prices."}], "figures": [], "verified_source_passages": ["Google , Amazon , Microsoft , and even OpenAI have launched their own custom processors to lessen their dependence on Nvidia; even if those chips aren’t as good as the latest model from Nvidia, they’re good enough to drive down the price of compute."], "source_passages_repaired": [true]}, {"local_id": "ev-4", "summary": "Ornn co-founder and CTO Wayne Nelms told TechCrunch that more GPU and accelerator players are entering the market, that everyone wants to make their own silicon but no one is making their own DRAM, and that absent a breakthrough on HBM (high-bandwidth memory) or a shift in memory supply and demand, current conditions will more or less persist.", "source_passages": ["“More GPU and accelerator players are entering the market. Everyone wants to make their own silicon, but no one is making their own DRAM,” Nelms told me.", "“Until there's a major technological breakthrough on HBM [high-bandwidth memory], a shift in supply and demand, or someone new [enters the market in memory], I think things will more or less persist as we see today.”"], "original_party": "Wayne Nelms (Ornn co-founder and CTO)", "reporting_speaker": "Russell Brandom / TechCrunch", "tier": "third_party_view", "statement_date": null, "statement_date_text": null, "evidence_period": null, "links": [{"target_type": "new", "target_id": "new-compute-price", "relevance": "Expert view that more accelerator players are entering, supporting the expectation of continued pressure on Nvidia GPU compute prices."}, {"target_type": "new", "target_id": "new-memory-price", "relevance": "Expert view that no one makes their own DRAM and that conditions persist absent an HBM breakthrough, supporting the thesis on the persistence of high HBM/DRAM prices."}], "figures": [], "verified_source_passages": ["“More GPU and accelerator players are entering the market. Everyone wants to make their own silicon, but no one is making their own DRAM,” Nelms told me.", "“Until there’s a major technological breakthrough on HBM [high-bandwidth memory], a shift in supply and demand, or someone new [enters the market in memory], I think things will more or less persist as we see today.”"], "source_passages_repaired": [false, true]}], "unresolved_links": [], "figure_issues": [], "unfiled_evidence": [], "unlinked_new_thesis_ids": [], "new_thesis_ids": {"new-compute-price": "clean-12", "new-memory-price": "clean-13"}}

